const updateCaptureStatus = `-- name: UpdateCaptureStatus :one
UPDATE captures SET
    status           = $1,
    error            = $2,
    instruction_note = coalesce($3, instruction_note),
    updated_at       = now()
WHERE id = $4
RETURNING id, user_id, status, revision, origin, instruction_note, suggested_project_id, timezone, error, activity_batch_id, created_at, updated_at, confirmed_at
`

type UpdateCaptureStatusParams struct {
	Status          string
	Error           []byte
	InstructionNote *string
	ID              string
}

func (q *Queries) UpdateCaptureStatus(ctx context.Context, arg UpdateCaptureStatusParams) (Capture, error) {
	row := q.db.QueryRow(ctx, updateCaptureStatus,
		arg.Status,
		arg.Error,
		arg.InstructionNote,
		arg.ID,
	)
	var i Capture
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Status,
		&i.Revision,
		&i.Origin,
		&i.InstructionNote,
		&i.SuggestedProjectID,
		&i.Timezone,
		&i.Error,
		&i.ActivityBatchID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ConfirmedAt,
	)
	return i, err
}
